  function normalizeToken(value) {
    return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  }
  function unique(values) {
    return [...new Set(values.map((value) => String(value || '').replace(/\s+/g, ' ').trim()).filter(Boolean))];
  }
  const LOCATION_TOKENS = new Set(['bishan','bedok','hougang','bukit','merah','jalan','sin','ming','geylang','tampines','yishun','jurong','woodlands','serangoon','toa','payoh','sengkang','punggol','clementi','orchard','marine','parade','ang','mo','kio','pasir','ris','choa','chu','kang']);
  const DESCRIPTOR_TOKENS = new Set(['medical','clinic','health','care','family','medicine','doctors','doctor','centre','center','surgery','practice','group','services']);
  const TRAILING_GENERIC = new Set(['clinic','centre','center','surgery','practice','services']);
  function collapseGenericTail(value) {
    let tokens = String(value || '').split(/\s+/).filter(Boolean);
    const variants = [];
    while (tokens.length > 2 && TRAILING_GENERIC.has(normalizeToken(tokens[tokens.length - 1]))) {
      tokens = tokens.slice(0, -1);
      variants.push(tokens.join(' '));
    }
    return variants;
  }
  function removeLocationTokens(value) {
    const tokens = String(value || '').split(/\s+/).filter(Boolean);
    if (tokens.length < 3) return [];
    const nonLocationCount = tokens.filter((token) => !LOCATION_TOKENS.has(normalizeToken(token))).length;
    if (nonLocationCount < 2) return [];
    const filtered = tokens.filter((token, idx) => {
      const lower = normalizeToken(token);
      if (!LOCATION_TOKENS.has(lower)) return true;
      const descriptorAfter = tokens.slice(idx + 1).some((part) => DESCRIPTOR_TOKENS.has(normalizeToken(part)));
      const trailingLocation = idx === tokens.length - 1 && idx >= 2;
      const embeddedBranchLocation = idx > 0 && descriptorAfter;
      return !(trailingLocation || embeddedBranchLocation);
    });
    const collapsed = filtered.join(' ').replace(/\s+/g, ' ').trim();
    if (!collapsed || collapsed === String(value || '').trim()) return [];
    return [collapsed, ...collapseGenericTail(collapsed)];
  }
  function buildAliases(rawValue, cleanedValue) {
    const rawLoose = String(rawValue || '').replace(/[()]/g, ' ').replace(/\s+/g, ' ').trim();
    const cleaned = String(cleanedValue || '').replace(/[()]/g, ' ').replace(/\s+/g, ' ').trim();
    const base = [
      cleaned.length >= 4 ? cleaned : '',
      rawLoose,
      rawLoose.replace(/\s*@\s.*/i, '').trim(),
      rawLoose.split(/\s+by\s+/i)[0].trim(),
      String(rawValue || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/[()]/g, ' ').replace(/\s+/g, ' ').trim()
    ].filter(Boolean);
    const expanded = [];
    for (const variant of base) {
      expanded.push(variant);
      expanded.push(...removeLocationTokens(variant));
      expanded.push(...collapseGenericTail(variant));
    }
    return unique(expanded).filter((value) => value.length >= 2);
  }
  const raw = String($('Loop Over Items').item.json._search_company_name || $('Loop Over Items').item.json.company_name || '').trim();
  const cleanRaw = String(($('OpenRouter - Clean Name').item.json.choices?.[0]?.message?.content || $('OpenRouter - Clean Name').item.json.body?.choices?.[0]?.message?.content || raw)).trim();
  const rawLoose = raw.replace(/[()]/g, ' ').replace(/\s+/g, ' ').trim();
  const aliases = buildAliases(raw, cleanRaw).filter((value) => String(value || '').trim().length >= 4);
  const negatives = ['-site:facebook.com','-site:linkedin.com','-site:instagram.com','-site:healthhub.sg','-site:moh.gov.sg','-site:findhealthclinics.com','-site:recordowl.com','-site:wherecrowded.sg','-site:yellowpages.com.sg','-site:gobusiness.gov.sg','-site:straitstimes.com','-site:channelnewsasia.com','-site:todayonline.com','-site:wheree.com','-site:clinicgeek.com','-site:vymaps.com','-site:sgpbusiness.com','-site:threebestrated.sg','-site:practo.com','-site:ubiehealth.com','-site:sgpgrid.com','-site:worldorgs.com','-site:aic.sg','-site:zhihu.com','-site:quora.com','-site:contact.page','-site:locallead.ai','-site:99.co','-site:activeasia.co','-site:unifiedlisting.com'];
